function calcularDano(ataque, defesa) {
  const dano = ataque - defesa;
  if (dano < 1) {
    return 1;
  }
  return dano;
}

function golpesParaVencer(vida, dano) {
  let restante = vida;
  let golpes = 0;
  while (restante > 0) {
    restante -= dano;
    golpes++;
  }
  return golpes;
}

console.log(calcularDano(10, 4));
console.log(golpesParaVencer(100, 30));

