function barraDeVida(vida, maximo = 10, simbolo = "#") {
  let barra = "";
  for (let i = 1; i <= maximo; i++) {
    if (i <= vida) {
      barra += simbolo;
    } else {
      barra += ".";
    }
  }
  return barra;
}

