function piramide(andares) {
  if (andares === 0) {
    return 0;
  }
  return andares + piramide(andares - 1);
}

function somaDigitos(n) {
  if (n < 10) {
    return n;
  }
  return (n % 10) + somaDigitos(Math.floor(n / 10));
}

