const DIGITOS = "0123456789";
const MAIUSCULAS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
const MINUSCULAS = "abcdefghijklmnopqrstuvwxyz";
const SIMBOLOS = "!@#$%&*?-_.";

function contar(texto, grupo) {
  let quantos = 0;
  for (const c of texto) {
    if (grupo.includes(c)) {
      quantos++;
    }
  }
  return quantos;
}

function validarSenha(senha, minimo = 8) {
  if (senha.length < minimo) {
    return `Use pelo menos ${minimo} caracteres.`;
  }
  if (contar(senha, DIGITOS) === 0) {
    return "Use pelo menos um número.";
  }
  if (contar(senha, MAIUSCULAS) === 0) {
    return "Use pelo menos uma letra maiúscula.";
  }
  if (contar(senha, MINUSCULAS) === 0) {
    return "Use pelo menos uma letra minúscula.";
  }
  if (contar(senha, " ") > 0) {
    return "A senha não pode ter espaços.";
  }
  return "Senha válida!";
}

function forcaDaSenha(senha) {
  if (validarSenha(senha) !== "Senha válida!") {
    return "fraca";
  }
  if (senha.length >= 12 && contar(senha, SIMBOLOS) > 0) {
    return "forte";
  }
  return "média";
}

console.log(validarSenha("abc"));
console.log(forcaDaSenha("Dragao#Verde123"));
